import{_ as a,O as r,H as t,f as i,i as n,k as s,b as d}from"./chunks/framework.Ch3ZxHbh.js";const g=JSON.parse('{"title":"A new indicator for working from home and what Black Friday has to do with it","description":"","frontmatter":{},"headers":[],"relativePath":"blog/home-office-black-friday.md","filePath":"blog/home-office-black-friday.md"}'),h={name:"blog/home-office-black-friday.md"};function l(m,e,c,f,w,p){const o=r("YoYChart");return t(),i("div",null,[e[0]||(e[0]=n('<h1 id="a-new-indicator-for-working-from-home-and-what-black-friday-has-to-do-with-it" tabindex="-1">A new indicator for working from home and what Black Friday has to do with it <a class="header-anchor" href="#a-new-indicator-for-working-from-home-and-what-black-friday-has-to-do-with-it" aria-label="Permalink to &quot;A new indicator for working from home and what Black Friday has to do with it&quot;">​</a></h1><div class="byline"><span class="byline-author">Alexander Götz</span><span class="byline-date">1 December 2020</span></div><p>Working from home put new objects on consumers&#39; shopping lists. Where the home was mainly for living before, it now had to be fit for work too. Monitors, cables and other work items have been in high demand since spring (see e.g. <a href="https://www.bloomberg.com/news/articles/2020-03-17/pc-monitors-in-short-supply-as-virus-spurs-home-office-buying" target="_blank" rel="noreferrer">Bloomberg</a>).</p><p>trendEcon combined Google queries around the new normal of working from home into an index, covering the search terms <em>headset</em>, <em>monitor</em>, <em>mouse</em> and <em>hdmi</em>. You probably googled at least one of these in spring or autumn. The index moves strongly with the lockdowns: the March uptick was extremely strong, and after a summer decline demand for home-office electronics rose again.</p><p>A comparison with previous years shows that, despite the summer dip, interest stayed above the level of earlier summers. It is also striking that towards the end of November demand for electronics rises in every year shown.</p>',5)),s(o,{series:"ch/homeoffice",years:[2018,2019,2020],until:"12-01",roller:7,title:"Home-office index: year-on-year",subtitle:"7-day rolling average"}),e[1]||(e[1]=d("p",null,"The short answer for those November swings: Black Friday. The discount battle has been delighting Swiss consumers for a few years now. In the next post we look at how Black Friday and the Cyber Week that followed affected demand for electronics and their retailers, such as Galaxus and Interdiscount.",-1))])}const u=a(h,[["render",l]]);export{g as __pageData,u as default};
